#!/usr/bin/env bash
#
# Prisoners mined from the OCR of the 1974 run of The Black Panther
# (44 of 48 issues processed; Lincoln University scans). Sixteen new
# records across seven case clusters:
#
#  - Leavenworth: William Hurst, the only white Leavenworth Brother,
#    found hanged in his cell May 9, 1974; Carl Davis and Jessie Lee
#    Davis, held in solitary at the military Fort Leavenworth.
#  - Angola: Gilbert Montegut (tried with Herman Wallace, acquitted)
#    and Chester Jackson (the severed fourth defendant who turned
#    state's witness).
#  - USS Little Rock: Eulie Jessie, James Shempert, and Martin P.
#    Williams — three of the eleven Black sailors court-martialed in
#    Naples over the November 8, 1973 shipboard attack.
#  - Dallas: Cal Ray Biggins. Richmond: Junius "Boo Red" Underwood.
#  - Trenton: Daniel Hogan, scalded to death in December 1973.
#  - Concord: John Yancey. Oakland BPP raids: Naomi Williams (January)
#    and Constance Webb, Annette Roper, Lintonia Sheppard (April).
#
# All already present: the four core Leavenworth Brothers, Jesse Lopez,
# Armando Miramon, Herman Wallace, Pitts & Lee, Joseph Waddell, the
# San Quentin Six, Wesley Robert Wells, and the Wounded Knee leadership.
#
# Idempotent: prisoner:add refuses duplicates.
#
# Run from the repo root:  bash database/data/add-bp-1974-mining.sh

set -euo pipefail
cd "$(dirname "$0")/../.."

php artisan prisoner:add '{"name":"William Hurst","first_name":"William","last_name":"Hurst","description":"William Hurst was the only white defendant among the seven Leavenworth Brothers — prisoners indicted on February 13, 1974 on charges growing out of the July 31, 1973 rebellion in which large portions of Leavenworth Penitentiary burned. Charged with assault and kidnapping alongside Jesse Lopez and Armando Miramon, he answered the prosecution in the words of Che Guevara: we are not going to submit to injustice to get justice. On May 9, 1974, Hurst was found hanging dead in his cell in the Wyandotte County Jail in Kansas — an alleged suicide that fellow prisoners charged was a murder by guards, and which the Leavenworth Brothers Legal Offense/Defense Committee independently investigated. Reconstructed from The Black Panther, 1974 run.","race":"White","gender":"Male","era":"1970s","in_custody":false,"released":false,"death_date":"1974-05-09","death_in_custody_date":"1974-05-09","cases":[{"institution_name":"Leavenworth Penitentiary","institution_city":"Leavenworth","institution_state":"Kansas","charges":"Assault and kidnapping — one of the seven Leavenworth Brothers indicted February 13, 1974 over the July 31, 1973 Leavenworth rebellion","convicted":"No — died before trial; found hanged in the Wyandotte County Jail on May 9, 1974, a death fellow prisoners charged was a guard killing"}]}' || true

php artisan prisoner:add '{"name":"Gilbert Montegut","first_name":"Gilbert","last_name":"Montegut","description":"Gilbert Montegut, 23, was one of the four Angola prisoners charged in the April 1972 killing of prison guard Brent Miller — the case that produced the Angola 3. Tried alongside Herman Wallace in Baton Rouge beginning January 7, 1974, in a trial The Black Panther described as marked with contradictions, inconsistencies and surprise — the fourth defendant, Chester Jackson, turned prosecution witness at its start — Montegut was acquitted while Wallace was convicted. Reconstructed from The Black Panther, 1974 run.","state":"Louisiana","race":"Black","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"Louisiana State Penitentiary (Angola)","institution_city":"Angola","institution_state":"Louisiana","charges":"Murder of Angola guard Brent Miller (April 1972) — tried with Herman Wallace, January 1974, Baton Rouge","convicted":"No — acquitted"}]}' || true

php artisan prisoner:add '{"name":"Chester Jackson","first_name":"Chester","last_name":"Jackson","description":"Chester Jackson, 30, was one of the four Angola prisoners charged in the April 1972 killing of guard Brent Miller alongside Herman Wallace, Albert Woodfox and Gilbert Montegut. At the start of the January 1974 Baton Rouge trial he had what The Black Panther called a sudden change of heart and became the prosecution'"'"'s star witness; his own trial was severed and was expected to proceed on a lesser charge. Reconstructed from The Black Panther, 1974 run; his later disposition has not been located.","state":"Louisiana","race":"Black","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"Louisiana State Penitentiary (Angola)","institution_city":"Angola","institution_state":"Louisiana","charges":"Charged in the April 1972 killing of Angola guard Brent Miller; trial severed after he became the prosecution'"'"'s witness against Wallace and Montegut","convicted":"Unknown — expected to be tried on a lesser charge; disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Carl Davis","first_name":"Carl","last_name":"Davis","description":"Carl Davis was a military prisoner at the United States Disciplinary Barracks, Fort Leavenworth, held in solitary confinement with Jessie Lee Davis on assault charges that a fellow prisoner, writing to The Black Panther in January 1974, called an indirect way of removing the brothers from the main population because of their political beliefs. Reconstructed from The Black Panther, January 19, 1974; disposition not located.","race":"Black","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"United States Disciplinary Barracks, Fort Leavenworth","institution_city":"Fort Leavenworth","institution_state":"Kansas","charges":"Assault — held in solitary confinement, charges fellow prisoners described as retaliation for his political beliefs","convicted":"Unknown — disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Jessie Lee Davis","first_name":"Jessie","middle_name":"Lee","last_name":"Davis","description":"Jessie Lee Davis was a military prisoner at the United States Disciplinary Barracks, Fort Leavenworth, held in solitary confinement with Carl Davis on charges over his supposed part in an attack — charges a fellow prisoner, writing to The Black Panther in January 1974, called an indirect way of removing the brothers from the main population because of their political beliefs. Reconstructed from The Black Panther, January 19, 1974; disposition not located.","race":"Black","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"United States Disciplinary Barracks, Fort Leavenworth","institution_city":"Fort Leavenworth","institution_state":"Kansas","charges":"Assault — held in solitary confinement, charges fellow prisoners described as retaliation for his political beliefs","convicted":"Unknown — disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Eulie Jessie","first_name":"Eulie","last_name":"Jessie","description":"Eulie Jessie was a Black sailor aboard the aircraft carrier USS Little Rock, flagship of the Sixth Fleet, where Black crewmen were outnumbered 50 to 1,300. The November 8, 1973 shipboard conflict began when a white seaman, William Linley, struck Jessie in the head with a wrench and called him a racial slur; at least 200 white sailors then attacked the Black crewmen. Eleven Black sailors — and no white ones — were court-martialed for riot and assault, tried in Naples, Italy, far from their communities. Jessie charged that Captain P. K. Cullins had been and still is lying about the incident; in October 1974 the Court of Military Appeals ruled that Cullins was a participant in the events and had illegally convened the courts, and he was dismissed as commander of the Naval Support Activity Base. Reconstructed from The Black Panther, 1974 run; individual dispositions not located.","gender":"Male","race":"Black","era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Riot and assault — one of the eleven Black USS Little Rock sailors court-martialed in Naples over the November 8, 1973 shipboard attack that began when he was struck with a wrench by a white crewman","convicted":"Unknown — the Court of Military Appeals ruled the convening officer illegally convened the courts; disposition not located"}]}' || true

php artisan prisoner:add '{"name":"James Shempert","first_name":"James","last_name":"Shempert","description":"James Shempert was one of the eleven Black sailors — and no white ones — court-martialed for riot and assault after the November 8, 1973 racial attack aboard the USS Little Rock, in which at least 200 white sailors set upon the ship'"'"'s outnumbered Black crewmen. Tried in Naples, Italy, he told The Black Panther that petty officers are writing us up on jive tips and that whether we were right or not the captain would burn us, concluding: as long as there is breath in my body I will fight the man and his system until it changes or until I die, whichever comes first. Reconstructed from The Black Panther, 1974 run; individual dispositions not located.","gender":"Male","race":"Black","era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Riot and assault — one of the eleven Black USS Little Rock sailors court-martialed in Naples over the November 8, 1973 shipboard attack","convicted":"Unknown — the Court of Military Appeals ruled the convening officer illegally convened the courts; disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Martin P. Williams","first_name":"Martin","last_name":"Williams","description":"Martin P. Williams reported aboard the USS Little Rock on July 6, 1973; by November 8, he said, I discovered the true meaning of racism. He was one of the eleven Black sailors — and no white ones — court-martialed for riot and assault after at least 200 white sailors attacked the ship'"'"'s outnumbered Black crewmen, and was tried in Naples, Italy. I wanted to serve my country, he told The Black Panther, but this special court-martial has turned me against the Navy and the government. Reconstructed from The Black Panther, 1974 run; individual dispositions not located.","gender":"Male","race":"Black","era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Riot and assault — one of the eleven Black USS Little Rock sailors court-martialed in Naples over the November 8, 1973 shipboard attack","convicted":"Unknown — the Court of Military Appeals ruled the convening officer illegally convened the courts; disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Cal Ray Biggins","first_name":"Cal","middle_name":"Ray","last_name":"Biggins","description":"Cal Ray Biggins was an 18-year-old Black Dallas youth indicted by the Dallas County grand jury for the January 7, 1974 murder of an elderly couple in their store. He was arrested four days later after a 5,000-dollar reward was offered and a paid informer called police to implicate him. The Black Panther reported the case as a frame-up; more than fifty supporters organized around his aunt, Mrs. Roberta King, with the Dallas Chapter of the Party. Reconstructed from The Black Panther, February 23, 1974; disposition not located.","state":"Texas","race":"Black","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"Dallas County Jail","institution_city":"Dallas","institution_state":"Texas","charges":"Murder — indicted January 1974 for the killing of an elderly couple; implicated by a paid informer after a reward was posted, in what the movement press reported as a frame-up","arrest_date":"1974-01-11","convicted":"Unknown — disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Junius Underwood","first_name":"Junius","last_name":"Underwood","aka":"Boo Red","description":"Junius \"Boo Red\" Underwood was a Black Panther Party member from Richmond, Virginia. Arrested at seventeen, he was given the maximum penalty — a five-year sentence — and sent to serve it in an adult institution, the Petersburg Federal Reformatory. His family, friends and comrades organized The Concerned Citizens for the Release of Junius Underwood to fight for his freedom. Reconstructed from The Black Panther, February 2, 1974; the charge and later disposition have not been located.","state":"Virginia","race":"Black","gender":"Male","affiliation":["Black Panther Party"],"ideologies":["Black liberation"],"era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"Petersburg Federal Reformatory","institution_city":"Petersburg","institution_state":"Virginia","charges":"Arrested at seventeen and given the maximum five-year sentence, served in an adult federal institution","convicted":"Yes — five years; disposition of release campaign not located"}]}' || true

php artisan prisoner:add '{"name":"Daniel Hogan","first_name":"Daniel","last_name":"Hogan","description":"Daniel Hogan, 21, was a prisoner at Trenton State Prison in New Jersey who was to be a key witness against guards in a suit brought by the family of 34-year-old R. Merrill Speller, who died at the Vroom readjustment unit. In December 1973, before he could testify, Hogan was scalded to death at the prison. In May 1974 the Mercer County grand jury refused to indict the guards responsible, absolving them of criminal neglect and charging them only with failure to use good judgement, noting their dismissal. Reconstructed from The Black Panther, January 19 and May 25, 1974.","state":"New Jersey","gender":"Male","era":"1970s","in_custody":false,"released":false,"death_date":"1973-12-15","death_in_custody_date":"1973-12-15","cases":[{"institution_name":"Trenton State Prison","institution_city":"Trenton","institution_state":"New Jersey","charges":"Imprisoned at Trenton State Prison; scalded to death by guards in December 1973 before he could testify against them — the grand jury refused to indict his killers","convicted":"Died in custody, December 1973"}]}' || true

php artisan prisoner:add '{"name":"John Yancey","first_name":"John","last_name":"Yancey","description":"John Yancey was a Black prisoner at the New Hampshire State Prison in Concord who, The Black Panther reported in March 1974, faced more than the usual amount of harassment both in and out of prison because he is proud, intelligent and Black. When eight guards led by Captain LaValle came to his cell an hour after nightlock and ordered him to back up to the bars to be handcuffed, he refused; after the guards assaulted him, he was the one charged with assaulting two of them — charges that could add ten to twenty years to his sentence plus twelve months in segregation. Reconstructed from The Black Panther, March 9, 1974; disposition not located.","state":"New Hampshire","race":"Black","gender":"Male","era":"1970s","in_custody":false,"released":true,"cases":[{"institution_name":"New Hampshire State Prison","institution_city":"Concord","institution_state":"New Hampshire","charges":"Assault on two prison guards — charges brought after guards assaulted him in his cell; he faced ten to twenty additional years and twelve months in segregation","convicted":"Unknown — disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Naomi Williams","first_name":"Naomi","last_name":"Williams","description":"Naomi Williams was a 19-year-old member of the Black Panther Party in Oakland. In January 1974 police mounted an armed action against a Party facility on the stated justification of serving a failure-to-appear warrant against her — she had been arrested the previous week for soliciting charitable donations without a permit while collecting for the People'"'"'s Free programs. Williams, in the office at the time, surrendered immediately to avoid endangering her comrades and the surrounding community. Reconstructed from The Black Panther, January 26, 1974.","state":"California","race":"Black","gender":"Female","affiliation":["Black Panther Party"],"ideologies":["Black liberation"],"era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Soliciting charitable donations without a permit — arrested while collecting for the Party'"'"'s survival programs, then subject of a failure-to-appear warrant served by an armed police action on a Party facility","convicted":"Unknown — disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Constance Webb","first_name":"Constance","last_name":"Webb","description":"Constance Webb was arrested in the April 1974 police raids on Black Panther Party facilities and homes in Oakland. Six months pregnant — a serious point in pregnancy, the Party noted at its press conference on the police attack — she was arrested and taken from her bed without an opportunity to change clothes. Reconstructed from the Party press conference text in The Black Panther, April 27, 1974; disposition not located.","state":"California","gender":"Female","affiliation":["Black Panther Party"],"era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Arrested in the April 1974 Oakland police raids on Black Panther Party facilities while six months pregnant, taken from her bed","convicted":"Unknown — the Party reported the raids as harassment; disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Annette Roper","first_name":"Annette","last_name":"Roper","description":"Annette Roper was arrested in the April 1974 police raids on Black Panther Party facilities and homes in Oakland, despite a serious asthmatic condition for which she was under almost daily medical care. Reconstructed from the Party press conference text in The Black Panther, April 27, 1974; disposition not located.","state":"California","gender":"Female","affiliation":["Black Panther Party"],"era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Arrested in the April 1974 Oakland police raids on Black Panther Party facilities","convicted":"Unknown — the Party reported the raids as harassment; disposition not located"}]}' || true

php artisan prisoner:add '{"name":"Lintonia Sheppard","first_name":"Lintonia","last_name":"Sheppard","description":"Lintonia Sheppard was responsible for the health care of the more than one hundred children at the Black Panther Party'"'"'s Intercommunal Youth Institute in Oakland, working with the East Oakland Health Alliance and Children'"'"'s Hospital. She was arrested in the April 1974 police raids on Party facilities and homes. Reconstructed from the Party press conference text in The Black Panther, April 27, 1974; disposition not located.","state":"California","gender":"Female","affiliation":["Black Panther Party"],"era":"1970s","in_custody":false,"released":true,"cases":[{"charges":"Arrested in the April 1974 Oakland police raids on Black Panther Party facilities","convicted":"Unknown — the Party reported the raids as harassment; disposition not located"}]}' || true

php artisan tinker --execute='
\Illuminate\Support\Facades\Cache::forget(\App\Http\Controllers\Api\PrisonerApiController::cacheKey());
echo "Done.\n";
'

echo
echo "Done. Black Panther 1974 mining batch applied (16 prisoners)."
